-- Add new schema named "agent"
CREATE SCHEMA "agent";
-- Create "agent_providers" table
CREATE TABLE "agent"."agent_providers" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "name" character varying NOT NULL, "kind" character varying NOT NULL, "base_url" character varying NULL, "model" character varying NOT NULL, "api_key_enc" character varying NOT NULL, "key_hint" character varying NOT NULL DEFAULT '', "is_default" boolean NOT NULL DEFAULT false, "capabilities" jsonb NULL, "workspace_id" bigint NOT NULL, "created_by" bigint NOT NULL, "updated_by" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "agent_providers_users_creator" FOREIGN KEY ("created_by") REFERENCES "core"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "agent_providers_users_updater" FOREIGN KEY ("updated_by") REFERENCES "core"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "agent_providers_workspaces_workspace" FOREIGN KEY ("workspace_id") REFERENCES "core"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "agentprovider_workspace_id" to table: "agent_providers"
CREATE UNIQUE INDEX "agentprovider_workspace_id" ON "agent"."agent_providers" ("workspace_id") WHERE is_default;
-- Create index "agentprovider_workspace_id_name" to table: "agent_providers"
CREATE UNIQUE INDEX "agentprovider_workspace_id_name" ON "agent"."agent_providers" ("workspace_id", "name");
